/**
 * @suppress
 */
public object FfiConverterTypeViewerSession: FfiConverter<ViewerSession, Pointer> {

    override fun lower(value: ViewerSession): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ViewerSession {
        return ViewerSession(value)
    }

    override fun read(buf: ByteBuffer): ViewerSession {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ViewerSession) = 8UL

    override fun write(value: ViewerSession, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



