    /**
     * Straight to the peer, once one has been validated.
     */
    var `direct`: PathInfo?, 
    /**
     * Whether the traffic is on the relay right now.
     */
    var `onRelay`: kotlin.Boolean, 
    /**
     * Whether [`ViewerSession::migrate`] would do anything.
     */
    var `canMigrate`: kotlin.Boolean
) {
    
    companion object
}

