/**
 * Errors surfaced across the FFI boundary.
 */
sealed class ClientException: kotlin.Exception() {
    
    class InvalidKey(
        
        val v1: kotlin.String
        ) : ClientException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidArgument(
        
        val v1: kotlin.String
        ) : ClientException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Connect(
        
        val v1: kotlin.String
        ) : ClientException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The camera answered as an Endpoint other than the one it was paired as.
     *
     * Apart from [`Self::Connect`] because it is not a transient failure and
     * retrying it is wrong: it says the introduction changed, and it will say
     * so again every time until the pairing is redone.
     */
    class WrongPeer(
        
        val v1: kotlin.String
        ) : ClientException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Runtime(
        
        val v1: kotlin.String
        ) : ClientException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ClientException> {
        override fun lift(error_buf: RustBuffer.ByValue): ClientException = FfiConverterTypeClientError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeClientError : FfiConverterRustBuffer<ClientException> {
    override fun read(buf: ByteBuffer): ClientException {
        

        return when(buf.getInt()) {
            1 -> ClientException.InvalidKey(
                FfiConverterString.read(buf),
                )
            2 -> ClientException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            3 -> ClientException.Connect(
                FfiConverterString.read(buf),
                )
            4 -> ClientException.WrongPeer(
                FfiConverterString.read(buf),
                )
            5 -> ClientException.Runtime(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ClientException): ULong {
        return when(value) {
            is ClientException.InvalidKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ClientException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ClientException.Connect -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ClientException.WrongPeer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ClientException.Runtime -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: ClientException, buf: ByteBuffer) {
        when(value) {
            is ClientException.InvalidKey -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ClientException.InvalidArgument -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ClientException.Connect -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ClientException.WrongPeer -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ClientException.Runtime -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
